#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# Copyright (C) 2026 Busbar Inc and contributors
#
# The `sbom` suite of testing/conformance/suites.tsv: a CycloneDX SBOM of the shipped `busbar` binary,
# generated by cargo-cyclonedx and validated by cyclonedx-cli, in the three legs, and one verdict:
#   1. CONTROL           a third-party known-good SBOM (the CycloneDX specification repo's own valid
#                        fixture, pinned by commit and sha256) validates.
#   2. NEGATIVE CONTROL  must be refused: the specification's own invalid fixture; the subject SBOM with
#                        a component's required `name` deleted (the validator refuses it); the subject
#                        SBOM with a whole crate dropped (still schema-valid, so the cross-check against
#                        `cargo metadata` must name that exact crate).
#   3. SUBJECT           the SBOM cargo-cyclonedx writes for crates/busbar validates AND lists exactly
#                        the crates `cargo metadata` resolves for the binary's closure (crosscheck.py).
# All three always run. `pass` only when all three hold. Writes $CONFORMANCE_OUT/verdict.json.
set -uo pipefail
: "${CONFORMANCE_OUT:?}"
repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
H="$repo/testing/sbom"
say() { printf 'sbom: %s\n' "$*" >&2; }

CX_VER=0.5.9          # cargo-cyclonedx
CLI_VER=v0.33.1       # cyclonedx-cli
SPEC_COMMIT=ad83dae28b236b8760286399da4daba77592de86   # CycloneDX/specification
SPEC_VALID_SHA=703dcdb016debf69f50b27728bdf6e9829a8235b6c9c28d365bcb29760b02e01
SPEC_INVALID_SHA=4d7772b356f7acf500c9e05e73f4088dd4399d763f594e598df6f76157ab050c
BOM_VERSION=v1_5

sha() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }
# fetch <url> <sha256> <dest>
fetch() {
  if [ -f "$3" ] && [ "$(sha "$3")" = "$2" ]; then return 0; fi
  mkdir -p "$(dirname "$3")" && curl -fsSL --retry 3 -o "$3.part.$$" "$1" || { rm -f "$3.part.$$"; say "download of $1 failed"; return 1; }
  [ "$(sha "$3.part.$$")" = "$2" ] || { say "sha256 mismatch for $1 (got $(sha "$3.part.$$"))"; rm -f "$3.part.$$"; return 1; }
  mv "$3.part.$$" "$3"
}

C="${MODERNCI_CACHE_DIR:-$HOME/.cache}/conformance-tools/sbom"
case "$(uname -s)-$(uname -m)" in
  Linux-x86_64)  CX_T=x86_64-unknown-linux-gnu;  CX_S=fb8dbee9f182173e062a64a387b21a0badc6fab8b2abf9294973f012972bf6d8; CLI_T=linux-x64;   CLI_S=bfc8b2538da86fe239bc53658bbb63c1c8c510a293c1e6891aa5bea5d3c58746 ;;
  Linux-aarch64) CX_T=aarch64-unknown-linux-gnu; CX_S=7bf131ca5389b07a4f10c182bcf8a5ad339d64408b6f0d8f6834a0bd6120a06a; CLI_T=linux-arm64; CLI_S=b2e9fdf9665ef49868a2ec012171c6e785dcd69745bc5869e53e4f4bfb096a5f ;;
  Darwin-arm64)  CX_T=aarch64-apple-darwin;      CX_S=4c53dfa21e70b65bf7f8d2592aadde3bcb02c1a40b6ec63b877e5ca65a29e180; CLI_T=osx-arm64;   CLI_S=750c148780154833f6401f9067d08c5a4c31567b6ee3c26c062c3a95c62d741c ;;
  Darwin-x86_64) CX_T=x86_64-apple-darwin;       CX_S=59d2a583fa632f8759456c1b531340331255b277386d23c598a3dbbc916fde63; CLI_T=osx-x64;     CLI_S=0ea92306fc7d7c30ed112a7463781a200585a3bf1cdaf77229181c5aabd1d4b6 ;;
  *) CX_T=""; CLI_T="" ;;
esac
export DOTNET_SYSTEM_GLOBALIZATION_INVARIANT=1 DOTNET_CLI_TELEMETRY_OPTOUT=1

W="$(mktemp -d "${TMPDIR:-/tmp}/sbom-conf.XXXXXX")"; trap 'rm -rf "$W"' EXIT
why=()

# ── the tools, sha256-pinned ───────────────────────────────────────────────────────────────────────
CX=""; CLI=""
if [ -z "$CX_T" ]; then why+=("no pinned cargo-cyclonedx/cyclonedx-cli for $(uname -s)-$(uname -m)")
else
  if fetch "https://github.com/CycloneDX/cyclonedx-rust-cargo/releases/download/cargo-cyclonedx-$CX_VER/cargo-cyclonedx-$CX_T.tar.xz" "$CX_S" "$C/cx-$CX_VER-$CX_T.tar.xz" \
     && mkdir -p "$W/cx" && tar -xJf "$C/cx-$CX_VER-$CX_T.tar.xz" -C "$W/cx" && CX="$(find "$W/cx" -name cargo-cyclonedx -type f | head -1)" && [ -n "$CX" ]; then :
  else why+=("cargo-cyclonedx $CX_VER could not be fetched, verified and unpacked"); CX=""; fi
  if fetch "https://github.com/CycloneDX/cyclonedx-cli/releases/download/$CLI_VER/cyclonedx-$CLI_T" "$CLI_S" "$C/cyclonedx-$CLI_VER-$CLI_T"; then
    CLI="$W/cyclonedx"; cp "$C/cyclonedx-$CLI_VER-$CLI_T" "$CLI" && chmod +x "$CLI"
  else why+=("cyclonedx-cli $CLI_VER could not be fetched and verified"); fi
fi
SPEC="https://raw.githubusercontent.com/CycloneDX/specification/$SPEC_COMMIT/tools/src/test/resources/1.5"
fetch "$SPEC/valid-bom-1.5.json" "$SPEC_VALID_SHA" "$C/spec-valid-bom-1.5.json" || why+=("the specification's valid fixture could not be fetched")
fetch "$SPEC/invalid-empty-component-1.5.json" "$SPEC_INVALID_SHA" "$C/spec-invalid-empty-component-1.5.json" || why+=("the specification's invalid fixture could not be fetched")

# validate <file>: cyclonedx-cli's verdict on a CycloneDX 1.5 JSON document (0 = valid).
validate() { "$CLI" validate --input-file "$1" --input-format json --input-version "$BOM_VERSION" --fail-on-errors >"$W/validate.log" 2>&1; }

if [ -n "$CLI" ]; then
  # ── leg 1: control ──
  say "=== leg 1: control (a third-party known-good SBOM validates)"
  validate "$C/spec-valid-bom-1.5.json" || { why+=("the control failed: the specification's own valid SBOM was refused"); cat "$W/validate.log" >&2; }
fi

# ── the subject SBOM and the metadata it is judged against ──────────────────────────────────────────
SBOM=""; META="$W/metadata.json"
if [ -n "$CX" ]; then
  say "=== generating the SBOM (cargo-cyclonedx $CX_VER over crates/busbar)"
  host="$(rustc -vV | sed -n 's/^host: //p')"
  before="$W/before.txt"; (cd "$repo" && git ls-files --others --exclude-standard -- '*.cdx.json' | sort) >"$before" 2>/dev/null || : >"$before"
  if (cd "$repo" && "$CX" cyclonedx --manifest-path crates/busbar/Cargo.toml --format json --spec-version 1.5 --describe binaries) >&2 \
     && [ -f "$repo/crates/busbar/busbar_bin.cdx.json" ]; then
    cp "$repo/crates/busbar/busbar_bin.cdx.json" "$W/busbar.cdx.json"; SBOM="$W/busbar.cdx.json"
  else why+=("cargo-cyclonedx wrote no SBOM for crates/busbar"); fi
  # cargo-cyclonedx writes beside every workspace member's manifest: remove what this run created.
  (cd "$repo" && git ls-files --others --exclude-standard -- '*.cdx.json' | sort | comm -13 "$before" - | while IFS= read -r f; do rm -f "$f"; done)
  (cd "$repo" && cargo metadata --format-version 1 --locked --filter-platform "$host" --manifest-path crates/busbar/Cargo.toml) >"$META" 2>"$W/meta.err" \
    || { why+=("cargo metadata failed: $(tail -1 "$W/meta.err")"); SBOM=""; }
fi

if [ -n "$SBOM" ] && [ -n "$CLI" ]; then
  # ── leg 3 (first half): the subject validates and matches the closure ──
  say "=== leg 3: subject (validates, and lists the whole shipped closure)"
  validate "$SBOM" || { why+=("the subject SBOM does not validate"); cat "$W/validate.log" >&2; }
  python3 -I "$H/crosscheck.py" check "$SBOM" "$META" >&2 || why+=("the subject SBOM does not match cargo metadata's closure for the shipped binary")

  # ── leg 2: negative controls ──
  say "=== leg 2: negative control (each of these MUST be refused)"
  if validate "$C/spec-invalid-empty-component-1.5.json"; then why+=("negative control: the specification's invalid SBOM was accepted"); else say "refused: the specification's invalid fixture"; fi
  victim="$(python3 -I "$H/crosscheck.py" corrupt "$SBOM" "$W/noname.json" missing-name)" || why+=("could not build the nameless-component SBOM")
  if validate "$W/noname.json"; then why+=("negative control: an SBOM with a component missing its required name ($victim) was accepted"); else say "refused: component $victim without a name"; fi
  victim="$(python3 -I "$H/crosscheck.py" corrupt "$SBOM" "$W/dropped.json" drop-crate)" || why+=("could not build the dropped-crate SBOM")
  validate "$W/dropped.json" || why+=("the dropped-crate SBOM should be schema-valid (the cross-check is the only thing that can catch it)")
  out="$(python3 -I "$H/crosscheck.py" check "$W/dropped.json" "$META" 2>&1)"; rc=$?
  if [ "$rc" -eq 0 ]; then why+=("negative control: the cross-check did not catch the dropped crate $victim")
  elif ! grep -qF "MISSING from the SBOM: $victim" <<<"$out"; then why+=("negative control: the cross-check failed but did not name the dropped crate $victim")
  else say "caught: the cross-check names the dropped crate $victim"; fi
elif [ -z "$SBOM" ]; then
  why+=("the subject SBOM could not be produced")
fi

python3 -I - "$CONFORMANCE_OUT/verdict.json" "$CX_VER" "$CLI_VER" "${why[@]+"${why[@]}"}" <<'PY'
import json, sys
out, cx, cli, why = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4:]
v = {"suite": "sbom", "status": "fail" if why else "pass", "armed": True,
     "standard": "CycloneDX 1.5 SBOM of the shipped busbar binary",
     "plan": "cargo-cyclonedx over crates/busbar, cyclonedx-cli validate, cross-checked against cargo metadata's closure",
     "spec_version": f"CycloneDX 1.5; cargo-cyclonedx {cx}; cyclonedx-cli {cli}"}
if why: v["reason"] = "; ".join(why)
json.dump(v, open(out, "w"), indent=2); open(out, "a").write("\n")
print(json.dumps(v))
sys.exit(1 if why else 0)
PY
